WITH base AS (SELECT id, customer_id, device, browser, started_at, country, CASE WHEN browser = 'Firefox' THEN 1 ELSE 0 END is_firefox, YEAR(started_at) started_at_year FROM sessions WHERE started_at >= TO_DATE('2024-03-19') AND country IS NOT NULL) SELECT s.*, top1.web_event_page, top1.event_time FROM base s LEFT JOIN LATERAL (SELECT c.page AS web_event_page, c.event_time FROM web_events c WHERE c.session_id = s.id ORDER BY c.duration_sec DESC, c.id DESC LIMIT 1) top1 ON TRUE;
